  Lemma seg_Hs : forall vals R M msF mo, 0 <= P <= 66 ->
    length vals = 323%nat -> vals_ev vals 0 = sp0 -> vals_ev vals 11 = Z_to_bv 64 2 -> vals_ev vals 141 = Z_to_bv 64 P ->
